def digest(value):
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def read_complete(path, wanted):
    raw = Path(path).read_bytes()
    if hashlib.sha256(raw).hexdigest() != wanted:
        raise ValueError("A complete original source changed: "+str(path))
    return raw.decode("utf-8")


def replace_exact(source, before, after):
    if source.count(before) != 1:
        raise ValueError("An exact full-source patch lost its unique original text")
    return source.replace(before, after, 1)


def construct(source_directory):
    directory = Path(source_directory)
    math = read_complete(directory/PARENT_MATH_NAME, PARENT_MATH_SHA256)
    radial = read_complete(directory/PARENT_RADIAL_NAME, PARENT_RADIAL_SHA256)
    start = math.index("def mean_jet_bounds(")
    end = math.index("\ndef ", start+4)
    original_function = math[start:end]
    if digest(original_function) != PARENT_MEAN_FUNCTION_SHA256:
        raise ValueError("The complete original mean-jet function changed")
    suffix = original_function[original_function.index("    profile_delta = length[\"profile_delta\"]"):]
    if digest(suffix) != RETAINED_COMPLETE_JET_SUFFIX_SHA256:
        raise ValueError("The complete retained R710/R711 suffix changed")
    kernel = KERNEL_SOURCE
    if kernel.count(suffix) != 1 or digest(kernel) != KERNEL_SHA256:
        raise ValueError("The entire independent R722 kernel is not the declared source")
    derived = radial
    for patch in RADIAL_PATCHES:
        derived = replace_exact(derived, patch["old"], patch["new"])
    if digest(derived) != RADIAL_SHA256:
        raise ValueError("The complete derived radial source changed")
    inverse = derived
    for patch in reversed(RADIAL_PATCHES):
        inverse = replace_exact(inverse, patch["new"], patch["old"])
    if inverse != radial:
        raise ValueError("The exact full radial text cannot be reversed")
    return {KERNEL_NAME: kernel, RADIAL_NAME: derived}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--source-directory", type=Path, required=True)
    parser.add_argument("--output-directory", type=Path, required=True)
    args = parser.parse_args()
    source = args.source_directory.resolve()
    target = args.output_directory.resolve()
    if target == source or target in source.parents:
        raise ValueError("Preserve the complete original sources in their own directory")
    outputs = construct(source)
    target.mkdir(parents=True, exist_ok=True)
    result = []
    for name, text in outputs.items():
        path = target/name
        if path.resolve() in {source/PARENT_MATH_NAME, source/PARENT_RADIAL_NAME}:
            raise ValueError("Do not overwrite an original complete source")
        path.write_text(text, encoding="utf-8", newline="")
        raw = path.read_bytes()
        if hashlib.sha256(raw).hexdigest() != digest(text):
            raise ValueError("A complete generated source changed while saving")
        result.append(dict(path=str(path), bytes=len(raw), sha256=digest(text)))
    print(json.dumps(dict(
        schema="complete-fixed-fejer-meridian-batched-R722-source-reconstruction-v1",
        sources=result, complete_original_jet_suffix_preserved=True,
        full_radial_text_reverse_verified=True,
        scientific_imports_or_calls_performed=False,
        numerical_fixtures_performed=False,
        admission_gate=False), sort_keys=True, indent=2))


if __name__ == "__main__":
    main()
